    commands: [`az network vnet create -g rg-net -n ${name} --address-prefixes ${cidr}`, `az network vnet subnet create -g rg-net --vnet-name ${name} -n snet-1 --address-prefixes ${base}/${subBits}`],
    commonMistakes: ["Picking a network address that is not aligned (e.g. 10.30.1.0/22).", "Subnets outside the VNet range."],
